window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5191542b904e6492"]={"versions": [{"id": "FIG-5191542b904e6492", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Paketdiagramm / High-Level Cluster-Übersicht (strukturelle Bausteindefinition).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Dient in der AUTOSAR Adaptive Platform (R20-11, <code>AUTOSAR_EXP_SWArchitecture</code>) der formalen Deklaration des Safety-Bereichs. Es verortet das <strong>Platform Health Management</strong> (PHM, im Diagramm als Paket <em>Platform Health Monitor</em> geführt) als den zentralen, normativen funktionalen Cluster (Functional Cluster) für funktionale Sicherheit (ISO 26262) innerhalb der AUTOSAR Adaptive Services.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Entitäten:</strong></li>\n<li><strong><code>Platform Health Monitor</code> (UML-Package):</strong> Repräsentiert den Functional Cluster <em>Platform Health Management</em> (<code>ara::phm</code>). Keine inneren Klassen, Ports oder Beziehungen grafisch im Schaubild ausdetailliert (atomare Cluster-Deklaration).</li>\n<li><strong>Architektonische Einbindung gemäß Spezifikationskontext (<code>AUTOSAR_SWS_PlatformHealthManagement</code>):</strong></li>\n<li><strong>Supervised Entity (SE):</strong> Logische Einheiten innerhalb einer Adaptive Application (AA), die Prüfpunkte (<em>Checkpoints</em>) melden.</li>\n<li><strong>Interaktionsschnittstelle Applikation (<code>ara::phm</code>):</strong> Standardisierte C++ API zur Übermittlung von Kontrollfluss-Ereignissen (<code>ReportCheckpoint()</code>) via leichtgewichtige IPC.</li>\n<li><strong>Schnittstelle zu State Management (<code>ara::sm</code>):</strong> Signalisierung von Überwachungsfehlern zur Triggerung von Rekonfigurationen, Degradationsstufen oder <em>Recovery Actions</em>.</li>\n<li><strong>Schnittstelle zu Execution Management (<code>ara::exec</code>):</strong> Einleitung von Prozess-Restarts bei isolierten Fehlern deterministischer Applikationen.</li>\n<li><strong>Hardware Watchdog Interface:</strong> Anbindung an einen physischen Watchdog-Treiber zur Absicherung bei Ausfall des OS/Kernels.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obwohl das Schaubild rein strukturell ist, kapselt der Baustein folgende dynamische Überwachungspfade:</p>\n<ol class=\"fig-list\">\n<li><strong>Alive Supervision:</strong> Zyklische Validierung gemeldeter Checkpoints innerhalb konfigurierter oberer und unterer Schwellwerte.</li>\n<li><strong>Deadline Supervision:</strong> Validierung von minimalen/maximalen Latenzen zwischen zwei transitiven Checkpoints.</li>\n<li><strong>Logical Supervision (Control Flow):</strong> Validierung der Ausführungsreihenfolge gegen einen im Ausführungsmanifest hinterlegten Zustandsgraphen (Transition Table).</li>\n<li><strong>Health Channel Supervision:</strong> Aggregation und Auswertung externer/systemischer Statusmeldungen.</li>\n<li><strong>Eskalationspfad:</strong> Bei Verletzung einer Überwachungsregel Übergang des lokalen Status (<code>OK</code> $\\rightarrow$ <code>FAILED</code> / <code>EXPIRED</code>). Aggregation zum globalen Gesundheitsstatus, Triggerung des State Managements und ggf. Inhibierung des Hardware-Watchdog-Triggers (kontrollierter System-Reset).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ISO 26262 Einordnung:</strong> Zentraler Baustein zur Erreichung von ASIL-Einstufungen auf der Adaptive Platform (Überwachung von Zeit- und Logikfehlern sowie Beherrschung von Common-Cause-Ausfällen).</li>\n<li><strong>Applikations-Entwickler:</strong> Adaptive Applications müssen explizit im C++-Code instrumentiert werden (<code>ara::phm::SupervisedEntity</code> instanziieren, Checkpoints an Kontrollflussknoten melden). Determinismus und minimale Latenz der Reporting-Aufrufe sind einzuhalten.</li>\n<li><strong>Integrations- & Plattform-Konfiguration:</strong></li>\n<li>Definition aller <em>Supervised Entities</em>, <em>Checkpoints</em>, <em>Transitions</em> und <em>Toleranzfenster</em> im ARXML-Applikations- und System-Manifest.</li>\n<li>Exakte Abstimmung der Deadline-Zeiten auf Scheduling-Zyklen des zugrundeliegenden POSIX-Betriebssystems.</li>\n<li>Konfiguration des Zusammenspiels mit dem State Management für deterministische Ausfallreaktionen (Safe State).</li>\n</ul>"}, {"id": "FIG-ff5f49b1b3b86e67", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Paketdiagramm / High-Level Cluster-Übersicht (strukturelle Bausteindefinition).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Dient in der AUTOSAR Adaptive Platform (<code>AUTOSAR_EXP_SWArchitecture</code>) der formalen Deklaration des Safety-Bereichs. Es verortet das <strong>Platform Health Management</strong> (PHM, im Diagramm als Paket <em>Platform Health Management</em> geführt) als den zentralen, normativen funktionalen Cluster (Functional Cluster) für funktionale Sicherheit (ISO 26262) innerhalb der AUTOSAR Adaptive Services.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Entitäten:</strong></li>\n<li><strong><code>Platform Health Management</code> (UML-Package):</strong> Repräsentiert den Functional Cluster <em>Platform Health Management</em> (<code>ara::phm</code>). Keine inneren Klassen, Ports oder Beziehungen grafisch im Schaubild ausdetailliert (atomare Cluster-Deklaration).</li>\n<li><strong>Architektonische Einbindung gemäß Spezifikationskontext (<code>AUTOSAR_SWS_PlatformHealthManagement</code>):</strong></li>\n<li><strong>Supervised Entity (SE):</strong> Logische Einheiten innerhalb einer Adaptive Application (AA), die Prüfpunkte (<em>Checkpoints</em>) melden.</li>\n<li><strong>Interaktionsschnittstelle Applikation (<code>ara::phm</code>):</strong> Standardisierte C++ API zur Übermittlung von Kontrollfluss-Ereignissen (<code>ReportCheckpoint()</code>) via leichtgewichtige IPC.</li>\n<li><strong>Schnittstelle zu State Management (<code>ara::sm</code>):</strong> Signalisierung von Überwachungsfehlern zur Triggerung von Rekonfigurationen, Degradationsstufen oder <em>Recovery Actions</em>.</li>\n<li><strong>Schnittstelle zu Execution Management (<code>ara::exec</code>):</strong> Einleitung von Prozess-Restarts bei isolierten Fehlern deterministischer Applikationen.</li>\n<li><strong>Hardware Watchdog Interface:</strong> Anbindung an einen physischen Watchdog-Treiber zur Absicherung bei Ausfall des OS/Kernels.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obwohl das Schaubild rein strukturell ist, kapselt der Baustein folgende dynamische Überwachungspfade:</p>\n<ol class=\"fig-list\">\n<li><strong>Alive Supervision:</strong> Zyklische Validierung gemeldeter Checkpoints innerhalb konfigurierter oberer und unterer Schwellwerte.</li>\n<li><strong>Deadline Supervision:</strong> Validierung von minimalen/maximalen Latenzen zwischen zwei transitiven Checkpoints.</li>\n<li><strong>Logical Supervision (Control Flow):</strong> Validierung der Ausführungsreihenfolge gegen einen im Ausführungsmanifest hinterlegten Zustandsgraphen (Transition Table).</li>\n<li><strong>Health Channel Supervision:</strong> Aggregation und Auswertung externer/systemischer Statusmeldungen.</li>\n<li><strong>Eskalationspfad:</strong> Bei Verletzung einer Überwachungsregel Übergang des lokalen Status (<code>OK</code> $\\rightarrow$ <code>FAILED</code> / <code>EXPIRED</code>). Aggregation zum globalen Gesundheitsstatus, Triggerung des State Managements und ggf. Inhibierung des Hardware-Watchdog-Triggers (kontrollierter System-Reset).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ISO 26262 Einordnung:</strong> Zentraler Baustein zur Erreichung von ASIL-Einstufungen auf der Adaptive Platform (Überwachung von Zeit- und Logikfehlern sowie Beherrschung von Common-Cause-Ausfällen).</li>\n<li><strong>Applikations-Entwickler:</strong> Adaptive Applications müssen explizit im C++-Code instrumentiert werden (<code>ara::phm::SupervisedEntity</code> instanziieren, Checkpoints an Kontrollflussknoten melden). Determinismus und minimale Latenz der Reporting-Aufrufe sind einzuhalten.</li>\n<li><strong>Integrations- & Plattform-Konfiguration:</strong></li>\n<li>Definition aller <em>Supervised Entities</em>, <em>Checkpoints</em>, <em>Transitions</em> und <em>Toleranzfenster</em> im ARXML-Applikations- und System-Manifest.</li>\n<li>Exakte Abstimmung der Deadline-Zeiten auf Scheduling-Zyklen des zugrundeliegenden POSIX-Betriebssystems.</li>\n<li>Konfiguration des Zusammenspiels mit dem State Management für deterministische Ausfallreaktionen (Safe State).</li>\n</ul>"}], "trans": [{"from": "FIG-5191542b904e6492", "to": "FIG-ff5f49b1b3b86e67", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Paketbeschriftung</strong>: Die Beschriftung des UML-Pakets wurde von <code>Platform Health Monitor</code> zu <code>Platform Health Management</code> korrigiert/umbenannt.</li>\n</ul>"}]};
